/** What a call ended with. */
export type Sent = { readonly data: unknown; readonly response: FetchResponse; readonly requestId: string | null; readonly answer: Answer };

/** How the body of a success is taken: read and given to `<op>Response`, left to the caller, or
 * read as a stream (the timer stops at the headers, the listener stays until the stream ends). */
export type Mode = "data" | "raw" | "stream";

